      <AppModal v-model="versionsOpen" width="min(92vw,740px)"><h3 class="mb-5">Versões da integração</h3><p v-if="!flux.versions?.length">Nenhuma versão publicada. Use Salvar e publicar para criar a primeira.</p><div v-for="version in flux.versions" :key="version.id" class="version-row"><template v-if="renamingVersion===version.id"><v-text-field v-model="versionName" label="Nome da versão" density="compact" hide-details @keyup.enter="saveVersionName(version)" /><v-btn icon="mdi-check" size="small" variant="text" @click="saveVersionName(version)" /></template><template v-else><div class="version-description"><strong>{{ version.name }}</strong><small>{{ formatDate(version.created_at) }}</small></div><v-chip v-if="version.id===flux.published_version_id||version.active" size="small" color="primary">Publicada</v-chip><v-btn v-else variant="tonal" size="small" @click="restoreVersion(version)">Restaurar</v-btn><v-btn icon="mdi-pencil-outline" variant="text" size="small" aria-label="Renomear versão" @click="renamingVersion=version.id;versionName=version.name" /><v-btn icon="mdi-delete-outline" variant="text" size="small" aria-label="Excluir versão" :disabled="version.id===flux.published_version_id||version.active" @click="removeVersion(version)" /></template></div></AppModal>
      <AppModal v-model="executionsOpen" width="min(92vw,880px)"><div class="executions-heading"><h3>Execuções</h3><v-btn variant="text" color="primary" :to="{name:'flux-dashboard',params:{fluxId:flux.id}}">Histórico de execuções <v-icon icon="mdi-open-in-new" size="16" class="ml-2" /></v-btn></div><p v-if="!flux.executions?.length">Nenhuma execução realizada.</p><div v-for="execution in flux.executions" :key="execution.id" class="execution-row"><v-icon :icon="execution.status==='error'?'mdi-alert-circle':'mdi-check-circle'" :color="execution.status==='error'?'error':'success'" size="21" /><div><strong>{{ formatDate(execution.started_at) }}</strong><small>{{ execution.origin }} · {{ execution.duration_ms??0 }} ms · {{ execution.operations??0 }} operações</small></div><v-btn size="small" variant="tonal" @click="lastExecution=execution;executionsOpen=false;terminalOpen=true;terminalTab='logs';selectedLog=null">Ver logs</v-btn></div></AppModal>
    </template>
  </div>
</template>

